using Freecrmlance.Domain.Audits;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;namespace Freecrmlance.Infrastructure.Persistence.Configurations;public sealed class AuditSectionConfiguration:IEntityTypeConfiguration<AuditSection>{public void Configure(EntityTypeBuilder<AuditSection>b){b.ToTable("AuditSections","audit");b.HasKey(x=>x.Id);b.Property(x=>x.Title).HasMaxLength(200).IsRequired();b.Property(x=>x.Description).HasMaxLength(2000);b.HasIndex(x=>new{x.AuditId,x.Position}).IsUnique();b.HasMany(x=>x.Items).WithOne().HasForeignKey(x=>x.AuditSectionId).OnDelete(DeleteBehavior.Cascade);b.Navigation(x=>x.Items).UsePropertyAccessMode(PropertyAccessMode.Field);}}
